def load() -> pd.DataFrame:
    import pandas as pd, glob
    paths = sorted(glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv'))
    rows = []
    for p in paths[:3] + paths[-3:]:
        df = pd.read_csv(p)
        rows.append({'path': p, 'nrows': len(df), 'ncols': df.shape[1], 'columns': list(df.columns)})
    return pd.DataFrame(rows)
